const KONTUR = '#1d1b1a';
const ton = (K, f) => (f > 0 ? hell(K.c, f) : f < 0 ? dunkel(K.c, -f) : K.c);

export function b04Zeichner(S, t, p) {
  const D = B04_DATEN[p.b04];
  if (!D) return;
  if (!S.tex && p.muster && p.muster !== 'uni' && istMuster(p.muster)) S.tex = musterFuellung(S, p.muster);
  // Musterfeld ersetzt das Bildmuster: Engine-Muster gesetzt (produkt.js leert dann p.dessin, auch bei uni) oder Silhouette mit eigenem Muster
  const ersetzt = p.dessin === '' || (p.muster && p.muster !== 'uni');
  // Feine Nadelstreifen als Standarddessin (Caprihose), solange das Musterfeld nichts anderes setzt
  if (p.feinstreifen && !p.muster && (!S.tex || S.m === 'wolle')) { const id = S.id + 'fs'; S.defs.push(`<pattern id="${id}" width="1.9" height="4" patternUnits="userSpaceOnUse"><rect width="0.32" height="4" fill="${hell(S.c, 0.55)}" opacity="0.8"/></pattern>`); S.tex = `url(#${id})`; }
  const K = [S];
  const n = 1 + Math.max(0, ...D.regionen.filter((r) => ['t', 'r', 'm', 'mf'].includes(r[0])).map((r) => r[1]));
  for (let i = 1; i < n; i++) K.push(materialDefs(p.farben?.[i - 1] ?? 'grau', p.materialien?.[i - 1] ?? 'baumwolle', S.defs));
  // glatte Strickfläche: Maschenstruktur aus stoff.js weg (Musterfeld bleibt)
  if (p.glatt) K.forEach((k) => { if ((k.m === 'strick' || k.m === 'kaschmir' || k.m === 'merino') && k.tex === `url(#${k.id}t)`) k.tex = null; });   // nur die Maschenstruktur, nie ein Musterfeld
  let rip = null;
  if (D.regionen.some((r) => r[0] === 'r')) { rip = S.id + 'rp'; S.defs.push(`<pattern id="${rip}" width="1.15" height="4" patternUnits="userSpaceOnUse"><rect width="0.45" height="4" fill="#000" opacity="0.28"/><rect x="0.5" width="0.25" height="4" fill="#fff" opacity="0.08"/></pattern>`); }
  const clip = S.id + 'b04';
  S.defs.push(`<clipPath id="${clip}"><path d="${D.kontur}" fill-rule="evenodd"/></clipPath>`);
  t.push(`<ellipse cx="50" cy="${D.boden + 1.8}" rx="${Math.min(32, D.breite * 0.45).toFixed(1)}" ry="2.4" fill="#000" opacity="0.08"/>`);
  t.push(`<g clip-path="url(#${clip})">`);
  const mfDa = new Set();
  for (const r of D.regionen) {
    const d = r[r.length - 1];
    if (r[0] === 'mf') {
      // Zone ohne Musterteile aus dem Bild (feine Streifen, p.querstreifen = [zone, abstand]): Streifen im Code, Musterfeld ersetzt sie
      if (D.regionen.some((q) => q[0] === 'm' && q[1] === r[1])) continue;
      const k = K[r[1]];
      if (ersetzt) t.push(`<path d="${r[2]}" fill="${k.c}"/>`);
      else if (p.querstreifen && p.querstreifen[0] === r[1]) { const id = S.id + 'qs' + r[1], a = p.querstreifen[1] ?? 1.6; S.defs.push(`<pattern id="${id}" width="4" height="${a}" patternUnits="userSpaceOnUse"><rect width="4" height="${(a * 0.45).toFixed(2)}" fill="${dunkel(k.c, 0.55)}" opacity="0.75"/></pattern>`); t.push(`<path d="${r[2]}" fill="url(#${id})"/>`); }
      continue;
    }
    if (r[0] === 'm') {
      // Musterfeld an der Stelle des ersten Musterteils einsetzen (über den gestapelten Grundflächen, unter Schatten, Licht und Linien)
      if (ersetzt) { if (!mfDa.has(r[1])) { mfDa.add(r[1]); const k = K[r[1]]; for (const q of D.regionen) if (q[0] === 'mf' && q[1] === r[1]) { t.push(`<path d="${q[2]}" fill="${k.c}"/>`); if (k.tex) t.push(`<path d="${q[2]}" fill="${k.tex}"/>`); } } }
      else { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); }
    }
    else if (r[0] === 'ko') t.push(`<path d="${d}" fill="${KONTUR}" fill-rule="evenodd"/>`);
    else if (r[0] === 'k') t.push(`<path d="${d}" fill="${KONTUR}"/>`);
    else if (r[0] === 'f') t.push(`<path d="${d}" fill="${r[1]}"/>`);
    else if (r[0] === 'r') { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); t.push(`<path d="${d}" fill="url(#${rip})"/>`); }
    else { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); }
  }
  // Licht von links wie alle Stoffe (stoff.js); Glanzlichter stecken schon in den Tonflächen
  t.push(`<path d="${D.kontur}" fill="url(#${S.id}l)" fill-rule="evenodd"/>`);
  t.push('</g>');
}
